from collections.abc import Mapping
from typing import Any

from app.entities.category import Category
from app.errors import ConflictError, FieldError, NotFoundError, ValidationFailedError
from app.paging import Page
from app.unit_of_work import UnitOfWork

# Columns a client may send: the database fills the others
_FIELDS = frozenset({"name"})


class CategoryService:
    """Operations on categories. Repositories commit every write."""

    def __init__(self, uow: UnitOfWork) -> None:
        self._uow = uow

    def _validate_all(self, values: dict[str, Any], current: Category | None) -> None:
        """Checks the values against the rules of the "categories" table; raises ValidationFailedError with every problem."""
        creating = current is None
        errors: list[FieldError] = []
        for name in values.keys() - _FIELDS:
            errors.append(FieldError(name, "is not a field of Category"))
        if not creating:
            for name in values.keys() & {"id"}:
                errors.append(FieldError(name, "cannot be changed"))
        value = values.get("name")
        if value is None:
            if creating or "name" in values:
                errors.append(FieldError("name", "is required"))
        else:
            if isinstance(value, str) and len(value) > 60:
                errors.append(FieldError("name", "is longer than 60 characters"))
        if errors:
            raise ValidationFailedError("Category", errors)

    def _check_unique(self, values: dict[str, Any], current: Category | None) -> None:
        """Values that must be unique are not taken by another row."""
        name = values["name"] if "name" in values else (current.name if current is not None else None)
        if name is not None:
            other = self._uow.categories.get_by_name(name)
            if other is not None and other is not current:
                raise ConflictError("Category", "name is already taken", ("name",))

    def _check(self, values: dict[str, Any], current: Category | None) -> None:
        """Every check before a write: the values, the rows they point to, the unique values."""
        self._validate_all(values, current)
        self._check_unique(values, current)

    def _find(self, id: int) -> Category:
        """The Category with this key; NotFoundError when there is none."""
        entity = self._uow.categories.get_by_id(id)
        if entity is None:
            raise NotFoundError("Category", id)
        return entity

    def create_category(self, category: Category) -> Category:
        """Stores a new Category after checking it."""
        values = {name: getattr(category, name) for name in _FIELDS}
        self._check(values, None)
        created = self._uow.categories.insert(category)
        return created

    def get_category(self, id: int) -> Category:
        """The Category with this key; NotFoundError when there is none."""
        return self._find(id)

    def list_categories(self, offset: int = 0, limit: int = 50) -> Page[Category]:
        """A page of categories, by primary key."""
        return self._uow.categories.list(offset, limit)

    def update_category(self, id: int, changes: Mapping[str, Any]) -> Category:
        """Changes the given values of a Category."""
        values = dict(changes)
        current = self._find(id)
        self._check(values, current)
        for name, value in values.items():
            setattr(current, name, value)
        updated = self._uow.categories.update(current)
        return updated

    def delete_category(self, id: int) -> None:
        """Deletes a Category."""
        current = self._find(id)
        if self._uow.products.list_by_category_id(current.id):
            raise ConflictError("Category", "rows of products still point to it", ("products",))
        self._uow.categories.delete(current)

    def get_category_by_name(self, name: str) -> Category | None:
        """The Category with this name, or None."""
        return self._uow.categories.get_by_name(name)

